! ============================================================
! VML 互斥锁扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 310")   ! 创建互斥锁
!   call asm("SYSCALL 311")   ! 锁定
!   call asm("SYSCALL 312")   ! 解锁
!
! 注意: 仅在 OS 模式 (--mode os) 下可用
! ============================================================

! ============================================================
! SYSCALL 310 — MutexCreate
! 创建互斥锁
! 参数: 无
! 返回: R0 = mutex ID (>0 成功)
!
! Fortran 使用示例:
!   call asm("SYSCALL 310")
!   ! 返回: R0 = mutex ID, 保存此 ID 用于后续操作
! ============================================================

! ============================================================
! SYSCALL 311 — MutexLock
! 锁定互斥锁 (阻塞等待直到获取锁)
! 参数: R0 = mutex ID
! 返回: R0 = 0 成功, <0 错误
!
! Fortran 使用示例:
!   ! R0 = mutex ID
!   call asm("SYSCALL 311")
!   if (锁获取成功) then
!     ... 临界区代码 ...
!     call asm("SYSCALL 312")  ! 释放锁
!   end if
! ============================================================

! ============================================================
! SYSCALL 312 — MutexUnlock
! 解锁互斥锁
! 参数: R0 = mutex ID
! 返回: R0 = 0 成功, <0 错误
!
! Fortran 使用示例:
!   ! R0 = mutex ID
!   call asm("SYSCALL 312")
! ============================================================

! ============================================================
! 使用模式示例（概念性代码）:
!
! program mutex_example
!   implicit none
!   ! 1. 创建互斥锁
!   call asm("SYSCALL 310")
!   !   此时 R0 包含 mutex_id，保存之
!
!   ! 2. 锁定 -> 临界区 -> 解锁
!   call asm("SYSCALL 311")   ! 锁定
!   ! ... 访问共享数据 ...
!   call asm("SYSCALL 312")   ! 解锁
!
!   ! 注意: 互斥锁通常配合条件变量 (SYSCALL 313-316) 使用
!   !       参见 cond.f90
! end program mutex_example
! ============================================================
